{
  "name": "QuTech量子波形发生器（QWG）",
  "name_en": "QuTech Quantum Waveform Generator (QWG)",
  "manufacturer": "QuTech",
  "description": "一款面向量子实验的多通道任意波形发生器，可输出模拟波形、进行边带参数设置，并支持基于DIO码字的触发与校准，同时提供DAC相关温度、电压和校准读写功能。",
  "description_en": "A multi-channel arbitrary waveform generator for quantum experiments. It outputs analog waveforms, configures sideband parameters, supports DIO codeword triggering and calibration, and provides DAC-related temperature, voltage, and calibration access.",
  "tag_hints": [
    "arbitrary waveform generator",
    "quantum control pulses",
    "codeword triggering",
    "DIO calibration",
    "sideband generation",
    "DAC calibration",
    "SCPI instrument"
  ],
  "actions": [
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准DIO协议序列。",
      "description_en": "Calibrate the DIO protocol sequence."
    },
    {
      "action_name": "auto-create_waveform_real",
      "description": "创建实数波形并写入波形数据。",
      "description_en": "Create a real waveform and write waveform data to it."
    },
    {
      "action_name": "auto-delete_waveform",
      "description": "删除指定波形。",
      "description_en": "Delete the specified waveform."
    },
    {
      "action_name": "auto-delete_waveform_all",
      "description": "删除全部波形。",
      "description_en": "Delete all waveforms."
    },
    {
      "action_name": "auto-dio_calibrate",
      "description": "执行DIO输入校准。",
      "description_en": "Perform DIO input calibration."
    },
    {
      "action_name": "auto-dio_calibration_report",
      "description": "返回最近一次DIO校准报告。",
      "description_en": "Return the latest DIO calibration report."
    },
    {
      "action_name": "auto-new_waveform_real",
      "description": "新建指定长度的实数波形。",
      "description_en": "Create a new real waveform with the specified length."
    },
    {
      "action_name": "auto-output_dio_calibration_data",
      "description": "输出用于DIO校准的数据。",
      "description_en": "Output data used for DIO calibration."
    },
    {
      "action_name": "auto-send_waveform_data_real",
      "description": "发送实数波形数据到AWG内存。",
      "description_en": "Send real waveform data to AWG memory."
    },
    {
      "action_name": "auto-set_amplitude",
      "description": "设置通道幅度。",
      "description_en": "Set channel amplitude."
    },
    {
      "action_name": "auto-set_channel_gain_adjust",
      "description": "设置通道DAC增益校准值。",
      "description_en": "Set the channel DAC gain adjustment value."
    },
    {
      "action_name": "auto-set_dac_digital_value",
      "description": "直接设置DAC数字值。",
      "description_en": "Set the DAC digital value directly."
    },
    {
      "action_name": "auto-set_dio_active_index",
      "description": "设置DIO活动索引。",
      "description_en": "Set the DIO active index."
    },
    {
      "action_name": "auto-set_dio_mode",
      "description": "设置DIO模式。",
      "description_en": "Set the DIO mode."
    },
    {
      "action_name": "auto-set_offset",
      "description": "设置通道偏置。",
      "description_en": "Set channel offset."
    },
    {
      "action_name": "auto-set_output_state",
      "description": "设置通道输出状态。",
      "description_en": "Set channel output state."
    },
    {
      "action_name": "auto-set_run_mode",
      "description": "设置运行模式。",
      "description_en": "Set the run mode."
    },
    {
      "action_name": "auto-set_sideband_frequency",
      "description": "设置边带频率。",
      "description_en": "Set the sideband frequency."
    },
    {
      "action_name": "auto-set_sideband_phase",
      "description": "设置边带相位。",
      "description_en": "Set the sideband phase."
    },
    {
      "action_name": "auto-set_waveform",
      "description": "设置通道波形。",
      "description_en": "Set the channel waveform."
    },
    {
      "action_name": "auto-start",
      "description": "启动波形发生输出。",
      "description_en": "Start waveform generation output."
    },
    {
      "action_name": "auto-stop",
      "description": "停止波形发生输出。",
      "description_en": "Stop waveform generation output."
    },
    {
      "action_name": "auto-sync_sideband_generators",
      "description": "同步边带发生器。",
      "description_en": "Synchronize the sideband generators."
    },
    {
      "action_name": "auto-get_run_mode",
      "description": "获取运行模式。",
      "description_en": "Get the run mode."
    },
    {
      "action_name": "auto-get_output_state",
      "description": "获取通道输出状态。",
      "description_en": "Get channel output state."
    },
    {
      "action_name": "auto-get_amplitude",
      "description": "获取通道幅度。",
      "description_en": "Get channel amplitude."
    },
    {
      "action_name": "auto-get_offset",
      "description": "获取通道偏置。",
      "description_en": "Get channel offset."
    },
    {
      "action_name": "auto-get_waveform",
      "description": "获取通道波形。",
      "description_en": "Get the channel waveform."
    },
    {
      "action_name": "auto-get_wlist_size",
      "description": "获取波形列表大小。",
      "description_en": "Get the waveform list size."
    },
    {
      "action_name": "auto-get_wlist_name",
      "description": "获取波形列表名称。",
      "description_en": "Get a waveform list name."
    },
    {
      "action_name": "auto-get_wlist",
      "description": "获取波形列表。",
      "description_en": "Get the waveform list."
    },
    {
      "action_name": "auto-get_waveform_type",
      "description": "获取波形类型。",
      "description_en": "Get the waveform type."
    },
    {
      "action_name": "auto-get_waveform_length",
      "description": "获取波形长度。",
      "description_en": "Get the waveform length."
    },
    {
      "action_name": "auto-get_waveform_data_float",
      "description": "获取浮点波形数据。",
      "description_en": "Get floating-point waveform data."
    },
    {
      "action_name": "auto-get_sideband_frequency",
      "description": "获取边带频率。",
      "description_en": "Get the sideband frequency."
    },
    {
      "action_name": "auto-get_sideband_phase",
      "description": "获取边带相位。",
      "description_en": "Get the sideband phase."
    },
    {
      "action_name": "auto-get_dio_calibrate",
      "description": "获取DIO校准状态。",
      "description_en": "Get the DIO calibration state."
    },
    {
      "action_name": "auto-get_dio_active_index",
      "description": "获取DIO活动索引。",
      "description_en": "Get the DIO active index."
    },
    {
      "action_name": "auto-get_dio_mode",
      "description": "获取DIO模式。",
      "description_en": "Get the DIO mode."
    },
    {
      "action_name": "auto-get_dio_suitable_indexes",
      "description": "获取DIO可用索引列表。",
      "description_en": "Get the suitable DIO indexes."
    },
    {
      "action_name": "auto-get_dio_calibrated_inputs",
      "description": "获取已校准的DIO输入。",
      "description_en": "Get the calibrated DIO inputs."
    },
    {
      "action_name": "auto-get_dio_lvds",
      "description": "获取DIO LVDS连接状态。",
      "description_en": "Get the DIO LVDS connection status."
    },
    {
      "action_name": "auto-get_dio_interboard",
      "description": "获取DIO板间连接状态。",
      "description_en": "Get the DIO interboard connection status."
    },
    {
      "action_name": "auto-get_max_codeword_bits",
      "description": "获取最大码字位数。",
      "description_en": "Get the maximum number of codeword bits."
    },
    {
      "action_name": "auto-get_codewords_select",
      "description": "获取码字选择设置。",
      "description_en": "Get the codeword selection setting."
    },
    {
      "action_name": "auto-get_triggers_logic_input",
      "description": "获取触发逻辑输入值。",
      "description_en": "Get the trigger logic input values."
    },
    {
      "action_name": "auto-get_bitmap",
      "description": "获取通道码字位图。",
      "description_en": "Get the channel codeword bitmap."
    },
    {
      "action_name": "auto-get_iofront_temperature",
      "description": "获取IO前端板温度。",
      "description_en": "Get the IO front-board temperature."
    },
    {
      "action_name": "auto-get_fpga_temperature",
      "description": "获取FPGA温度。",
      "description_en": "Get the FPGA temperature."
    },
    {
      "action_name": "auto-get_dac_temperature",
      "description": "获取DAC温度。",
      "description_en": "Get the DAC temperature."
    },
    {
      "action_name": "auto-get_channel_output_voltage",
      "description": "获取通道输出电压。",
      "description_en": "Get the channel output voltage."
    },
    {
      "action_name": "auto-get_channel_gain_adjust",
      "description": "获取通道DAC增益校准值。",
      "description_en": "Get the channel DAC gain adjustment value."
    }
  ]
}

